<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Download, RefreshCw, Search } from 'lucide-vue-next'

type LogEntry = { id:string; source:string; service:string; level:string; event:string; message:string; integration?:string|null; error_code?:string|null; correlation_id?:string|null; request_id?:string|null; actor?:string|null; details?:Record<string,unknown>; created_at?:string|null; scope?:string }
type ApiEnvelope<T> = { data:T; error?:{message?:string;code?:string} }

const props = withDefaults(defineProps<{embedded?:boolean;tenantId?:string;tenantName?:string;tenantSlug?:string;tenantHostname?:string|null}>(),{embedded:false,tenantId:'',tenantName:'',tenantSlug:'',tenantHostname:null})
const loading=ref(false)
const logs=ref<LogEntry[]>([])
const search=ref('')
const level=ref('')
const error=ref('')
const downloading=ref(false)
const selected=ref(props.tenantId||'')
const visibleCount=ref(100)
const pageStep=100
const visibleLogs=computed(()=>logs.value.slice(0,visibleCount.value))
const hasMore=computed(()=>visibleCount.value<logs.value.length)
const stats=computed(()=>({total:logs.value.length,errors:logs.value.filter((item)=>['ERROR','CRITICAL'].includes(String(item.level).toUpperCase())).length,warnings:logs.value.filter((item)=>String(item.level).toUpperCase()==='WARNING').length}))
const tenantLabel=computed(()=>props.tenantName||props.tenantSlug||selected.value||'Tenant')
const tenantSubLabel=computed(()=>props.tenantHostname||props.tenantSlug||selected.value)

function sessionToken():string{try{const raw=localStorage.getItem('scheduler-pro-admin-session');if(!raw)return '';return String((JSON.parse(raw) as {accessToken?:string}).accessToken||'')}catch{return ''}}
async function api<T>(path:string):Promise<T>{const token=sessionToken();if(!token)throw new Error('Entre novamente no Control Plane para consultar os logs.');const response=await fetch(`/api/v1${path}`,{headers:{accept:'application/json',authorization:`Bearer ${token}`},cache:'no-store'});const payload=await response.json().catch(()=>({})) as Partial<ApiEnvelope<T>>;if(!response.ok)throw new Error(payload.error?.message||`Falha ao consultar o servidor (${response.status}).`);return payload.data as T}
async function loadLogs():Promise<void>{if(!selected.value){logs.value=[];return}loading.value=true;error.value='';visibleCount.value=pageStep;try{const params=new URLSearchParams({limit:'1000'});if(search.value.trim())params.set('search',search.value.trim());if(level.value)params.set('level',level.value);logs.value=await api<LogEntry[]>(`/platform/tenant-management/${selected.value}/logs?${params}`)}catch(exc){error.value=exc instanceof Error?exc.message:'Não foi possível carregar o diagnóstico do tenant.'}finally{loading.value=false}}
async function downloadBundle():Promise<void>{if(!selected.value)return;downloading.value=true;error.value='';try{const token=sessionToken();const response=await fetch(`/api/v1/platform/observability/logs/export?tenant=${encodeURIComponent(selected.value)}`,{headers:{authorization:`Bearer ${token}`}});if(!response.ok){const payload=await response.json().catch(()=>({})) as Partial<ApiEnvelope<unknown>>;throw new Error(payload.error?.message||'Não foi possível gerar o pacote de diagnóstico.')}const blob=await response.blob();const disposition=response.headers.get('content-disposition')||'';const match=disposition.match(/filename="?([^";]+)"?/i);const filename=match?.[1]||`scheduler-pro-${props.tenantSlug||'tenant'}-diagnostico.zip`;const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();URL.revokeObjectURL(url)}catch(exc){error.value=exc instanceof Error?exc.message:'Falha ao baixar o diagnóstico.'}finally{downloading.value=false}}
function formatDate(value?:string|null):string{return value?new Date(value).toLocaleString('pt-BR'):'—'}
function levelClass(value:string):string{return String(value||'INFO').toLowerCase()}
function showMore():void{visibleCount.value=Math.min(visibleCount.value+pageStep,logs.value.length)}
watch(()=>props.tenantId,(value)=>{selected.value=value||'';void loadLogs()})
onMounted(()=>{selected.value=props.tenantId||selected.value;if(selected.value)void loadLogs()})
</script>

<template>
  <section class="tenant-log-panel">
    <header class="tenant-log-panel-header"><div><span>Observabilidade persistente</span><h3>Logs e diagnóstico</h3><p>Histórico técnico deste tenant, disponível somente no Control Plane administrativo.</p></div><button type="button" :disabled="loading||!selected" @click="loadLogs"><RefreshCw :size="16"/>Atualizar</button></header>
    <div class="tenant-log-toolbar"><label>Buscar<div class="search"><Search :size="15"/><input v-model="search" placeholder="mensagem, rota, evento, código..." @keyup.enter="loadLogs"/></div></label><label>Nível<select v-model="level" @change="loadLogs"><option value="">Todos</option><option>INFO</option><option>WARNING</option><option>ERROR</option><option>CRITICAL</option></select></label><button class="primary" type="button" :disabled="!selected||downloading" @click="downloadBundle"><Download :size="16"/>{{downloading?'Gerando...':'Baixar diagnóstico completo'}}</button></div>
    <p v-if="error" class="tenant-log-error">{{error}}</p>
    <div class="tenant-log-summary"><article><span>Tenant</span><strong>{{tenantLabel}}</strong><small>{{tenantSubLabel}}</small></article><article><span>Eventos</span><strong>{{stats.total}}</strong><small>registros consultados</small></article><article><span>Erros</span><strong>{{stats.errors}}</strong><small>ERROR / CRITICAL</small></article><article><span>Avisos</span><strong>{{stats.warnings}}</strong><small>WARNING</small></article></div>
    <div class="tenant-log-list">
      <div v-if="loading" class="tenant-log-empty"><RefreshCw class="spin" :size="22"/> Carregando histórico persistente...</div>
      <template v-else>
        <article v-for="entry in visibleLogs" :key="`${entry.scope||'tenant'}-${entry.id}`" class="tenant-log-entry" :class="levelClass(entry.level)">
          <div class="meta"><time>{{formatDate(entry.created_at)}}</time><span>{{entry.level}}</span><strong>{{entry.service}}</strong><em v-if="entry.integration">{{entry.integration}}</em><em v-if="entry.scope">{{entry.scope==='platform'?'Control Plane':'Banco do tenant'}}</em></div>
          <div class="body"><h4>{{entry.event}}</h4><p>{{entry.message}}</p><div class="ids"><code v-if="entry.error_code">{{entry.error_code}}</code><code v-if="entry.correlation_id">corr {{entry.correlation_id}}</code><code v-if="entry.request_id">req {{entry.request_id}}</code></div><details v-if="entry.details&&Object.keys(entry.details).length"><summary>Detalhes técnicos</summary><pre>{{JSON.stringify(entry.details,null,2)}}</pre></details></div>
        </article>
        <div v-if="selected&&!logs.length" class="tenant-log-empty">Ainda não há eventos persistidos para este tenant. As novas operações e erros aparecerão aqui automaticamente.</div>
        <div v-if="hasMore" class="tenant-log-more"><span>Exibindo {{visibleLogs.length}} de {{logs.length}} eventos.</span><button type="button" @click="showMore">Carregar mais {{Math.min(pageStep,logs.length-visibleCount)}}</button></div>
      </template>
    </div>
  </section>
</template>

<style scoped>
.tenant-log-panel{display:grid;gap:12px;margin-top:0;padding:16px;border:1px solid #dfe7f1;border-radius:16px;background:#fff;color:#13233b;min-width:0}.tenant-log-panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.tenant-log-panel-header span{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:#2875e8}.tenant-log-panel-header h3{margin:4px 0;font-size:18px}.tenant-log-panel-header p{margin:0;color:#718096;font-size:11px;line-height:1.45}.tenant-log-panel-header button,.tenant-log-toolbar button,.tenant-log-more button{display:flex;align-items:center;justify-content:center;gap:7px;min-height:40px;border:1px solid #d9e2ed;border-radius:11px;background:#fff;font:inherit;font-size:11px;font-weight:850;cursor:pointer}.tenant-log-panel-header button:disabled,.tenant-log-toolbar button:disabled{opacity:.5;cursor:not-allowed}.tenant-log-toolbar{position:sticky;top:-1px;z-index:3;display:grid;grid-template-columns:minmax(0,1.3fr) minmax(130px,.55fr) auto;gap:9px;padding:8px 0;background:#fff;box-shadow:0 7px 12px -12px rgba(15,23,42,.55)}.tenant-log-toolbar label{display:grid;gap:5px;font-size:10px;font-weight:850;color:#69788e;text-transform:uppercase;letter-spacing:.04em}.tenant-log-toolbar select,.tenant-log-toolbar input{width:100%;box-sizing:border-box;height:42px;border:1px solid #d8e1ec;border-radius:11px;background:#fff;padding:0 11px;font:inherit;font-size:12px;color:#1a2c46;outline:none}.tenant-log-toolbar .search{position:relative}.tenant-log-toolbar .search svg{position:absolute;left:10px;top:13px;color:#8492a6}.tenant-log-toolbar .search input{padding-left:32px}.tenant-log-toolbar button.primary{align-self:end;border-color:#2563eb;background:linear-gradient(135deg,#0b1d3a,#19b9ed);color:#fff;padding:0 14px}.tenant-log-error{margin:0;padding:11px 13px;border:1px solid #fecaca;border-radius:11px;background:#fff1f2;color:#9f1239;font-size:11px;font-weight:750}.tenant-log-summary{display:grid;grid-template-columns:1.4fr repeat(3,.7fr);gap:8px}.tenant-log-summary article{min-height:78px;padding:12px;border:1px solid #e3e9f1;border-radius:13px;background:#f9fbfd}.tenant-log-summary span,.tenant-log-summary strong,.tenant-log-summary small{display:block}.tenant-log-summary span{font-size:9px;font-weight:900;text-transform:uppercase;color:#79889c;letter-spacing:.06em}.tenant-log-summary strong{margin:7px 0 3px;font-size:17px;overflow-wrap:anywhere}.tenant-log-summary small{font-size:9px;color:#8996a8;overflow-wrap:anywhere}.tenant-log-list{display:grid;gap:8px;min-width:0;overflow:visible}.tenant-log-entry{display:grid;grid-template-columns:155px minmax(0,1fr);border:1px solid #e0e7f0;border-left:4px solid #60a5fa;border-radius:13px;background:#fff;overflow:hidden}.tenant-log-entry.warning{border-left-color:#f59e0b}.tenant-log-entry.error,.tenant-log-entry.critical{border-left-color:#ef4444}.tenant-log-entry .meta{padding:11px;border-right:1px solid #edf1f6;background:#fafbfd}.tenant-log-entry .meta>*{display:block}.tenant-log-entry time{font-size:9px;color:#7c8ba0}.tenant-log-entry .meta span{width:max-content;margin:6px 0;padding:3px 6px;border-radius:999px;background:#eff6ff;color:#1d4ed8;font-size:8px;font-weight:900}.tenant-log-entry.error .meta span,.tenant-log-entry.critical .meta span{background:#fee2e2;color:#b91c1c}.tenant-log-entry .meta strong{font-size:10px}.tenant-log-entry .meta em{margin-top:3px;font-size:9px;color:#64748b;font-style:normal}.tenant-log-entry .body{min-width:0;padding:11px 13px}.tenant-log-entry h4{margin:0 0 4px;font-size:12px}.tenant-log-entry p{margin:0;color:#46566e;font-size:11px;line-height:1.5;overflow-wrap:anywhere}.tenant-log-entry .ids{display:flex;flex-wrap:wrap;gap:4px;margin-top:7px}.tenant-log-entry code{padding:3px 5px;border-radius:5px;background:#f1f5f9;color:#475569;font-size:8px;overflow-wrap:anywhere}.tenant-log-entry details{margin-top:7px}.tenant-log-entry summary{cursor:pointer;color:#2563eb;font-size:9px;font-weight:800}.tenant-log-entry pre{margin:7px 0 0;padding:10px;border-radius:8px;background:#0b1729;color:#dbeafe;font-size:9px;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;overflow:visible}.tenant-log-empty{padding:30px 16px;text-align:center;color:#758399;font-size:11px}.tenant-log-more{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border:1px dashed #cbd5e1;border-radius:12px;background:#f8fafc;color:#64748b;font-size:11px}.tenant-log-more button{min-height:34px;padding:0 12px;color:#075ea8}.spin{animation:tenant-log-spin 1s linear infinite}@keyframes tenant-log-spin{to{transform:rotate(360deg)}}@media(max-width:800px){.tenant-log-panel{padding:12px}.tenant-log-panel-header{display:grid}.tenant-log-panel-header button{width:100%}.tenant-log-toolbar{position:static;grid-template-columns:1fr 1fr}.tenant-log-toolbar label:first-child{grid-column:1/-1}.tenant-log-toolbar button.primary{grid-column:1/-1}.tenant-log-summary{grid-template-columns:1fr 1fr}.tenant-log-summary article:first-child{grid-column:1/-1}.tenant-log-entry{grid-template-columns:1fr}.tenant-log-entry .meta{border-right:0;border-bottom:1px solid #edf1f6}.tenant-log-entry .meta>*{display:inline-block;margin-right:5px}.tenant-log-entry .meta span{margin-top:0}.tenant-log-more{display:grid}.tenant-log-more button{width:100%}}
</style>
